SELECT w.id AS wallet_trade_id, w.signal_id, s1.symbol, UNIX_TIMESTAMP(s1.generated_at) AS gen1m_epoch, (SELECT s5.id FROM crypto_ai.trade_signal s5 WHERE s5.symbol=s1.symbol AND s5.interval_code='5m' AND s5.generated_at > s1.generated_at AND s5.generated_at <= s1.generated_at + INTERVAL 5 SECOND ORDER BY s5.generated_at LIMIT 1) AS newer_5m_id, (SELECT CONCAT(s5.decision,'|',s5.atr_immediate_entry_allowed,'|',s5.atr_recommended_position_percent) FROM crypto_ai.trade_signal s5 WHERE s5.symbol=s1.symbol AND s5.interval_code='5m' AND s5.generated_at > s1.generated_at AND s5.generated_at <= s1.generated_at + INTERVAL 5 SECOND ORDER BY s5.generated_at LIMIT 1) AS newer_5m_plan, w.realized_pnl_usdt FROM crypto_ai.wallet_trade w JOIN crypto_ai.trade_signal s1 ON s1.id=w.signal_id WHERE w.execution_reason='SETUP_TIMEFRAME_ATR' AND w.side='BUY' AND w.executed_at >= UTC_TIMESTAMP() - INTERVAL 14 DAY ORDER BY w.id LIMIT 50;